**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    int n = tab.size();

    int cnt = 1, maxCnt = 1;
    int start = 0, bestStart = 0, bestEnd = 0;
    for (int i = 1; i < n; i++) {
        if (tab[i] > tab[i - 1]) {
            cnt++;
        } else {
            if (cnt > maxCnt) {
                maxCnt = cnt;
                bestStart = start;
                bestEnd = i - 1;
            }
            cnt = 1;
            start = i;
        }
    }
    if (cnt > maxCnt) {
        maxCnt = cnt;
        bestStart = start;
        bestEnd = n - 1;
    }

    cout << "Najdluzszy ciag rosnacy: " << maxCnt << " elementow" << endl;
    cout << "Pozycja: od " << bestStart + 1 << " do " << bestEnd + 1 << endl;
    return 0;
}
```

**Wyjasnienie**: Skan liniowy z dwoma zmiennymi: biezaca dlugosc ciagu i najdluzsza dotychczas. Gdy ciag sie przerywa, porownujemy i resetujemy. Po petli sprawdzamy ostatni ciag.

Weryfikacja:
- Ciagi rosnace: [5,8,12] dlugosc 3 (poz. 1-3), [3,6,9,15,20] dlugosc 5 (poz. 4-8), [2,7] dlugosc 2 (poz. 9-10)
- Najdluzszy: 5 elementow, pozycja od 4 do 8.
